// -- Sub-components --

const ClusterHeader: React.FC<{
  name: string;
  lockHash: string;
  isLoading?: boolean;
  showExitButton?: boolean;
}> = ({ name, lockHash, isLoading, showExitButton }) => (
  <HeaderSection>
    <Flex css={{ alignItems: "center", gap: "$md" }}>
      <ClusterIcon size={32} color="currentColor" />
      {isLoading ? (
        <Box css={{ width: "200px" }}>
          <Skeleton variant="text" />
        </Box>
      ) : (
        <Flex css={{ flexDirection: "column", gap: "$xxs" }}>
          <Text variant="h3">{name}</Text>
          <Flex css={{ alignItems: "center", gap: "$xs" }}>
            <Text css={{ color: "$textLight", fontSize: "$2" }}>
              {lockHash.slice(0, 10)}...{lockHash.slice(-6)}
            </Text>
            <Link
              href={`https://holesky.etherscan.io/tx/${lockHash}`}
              target="_blank"
            >
              <OpenInNew size="sm" />
            </Link>
          </Flex>
        </Flex>
      )}
    </Flex>
    {showExitButton && <Button color="secondary">Exit Cluster</Button>}
  </HeaderSection>
);

const MetricsRow: React.FC<{
  isLoading?: boolean;
  status: ClusterStatus;
}> = ({ isLoading, status }) => (
  <Flex css={{ gap: "$lg", "@sm": { flexDirection: "column" } }}>
    <MetricWidget
      heading="Status"
      status={status}
      tooltipContent="The current status of this cluster"
      isLoading={isLoading}
    />
    <MetricWidget
      heading="Validators"
      content={isLoading ? "" : "5"}
      tooltipContent="The number of validators in this cluster"
      isLoading={isLoading}
    />
    <MetricWidget
      heading="Operators"
      content={isLoading ? "" : "4"}
      tooltipContent="The number of operators running this cluster"
      isLoading={isLoading}
    />
    <MetricWidget
      heading="Network"
      content={
        isLoading ? (
          ""
        ) : (
          <Flex css={{ alignItems: "center", gap: "$xs" }}>
            <EthIcon size={20} />
            <Text variant="h4">Holesky</Text>
          </Flex>
        )
      }
      tooltipContent="The network this cluster is running on"
      isLoading={isLoading}
    />
  </Flex>
);

// -- Page composition --

const MockClusterDetailsPage = ({
  isLoading = false,
  status = "active" as ClusterStatus,
  showExitButton = false,
  showPeerRankings = false,
  showNetworkMismatch = false,
}: {
  isLoading?: boolean;
  status?: ClusterStatus;
  showExitButton?: boolean;
  showPeerRankings?: boolean;
  showNetworkMismatch?: boolean;
}) => (
  <DarkBackground>
    <PageContainer>
      {showNetworkMismatch && (
        <NotificationCard
          heading="Network mismatch detected"
          subHeading="Your connected wallet is on a different network than this cluster. Please switch to Holesky to interact with this cluster."
          link="https://docs.obol.org"
          linkText="Learn more"
        />
      )}

      <ClusterHeader
        name={MOCK_CLUSTER_NAME}
        lockHash={MOCK_LOCK_HASH}
        isLoading={isLoading}
        showExitButton={showExitButton}
      />

      <MetricsRow isLoading={isLoading} status={status} />

      <BoxTable
        css={{
          ".table-container": {
            "@sm": {
              minWidth: "694px",
              width: "fit-content",
              overflowX: "scroll",
            },
          },
        }}
      >
        <TableContainerWithTabs
          isLoading={isLoading}
          tabs={[
            {
              title: "Operators",
              count: mockOperatorRows.length,
              tableProps: {
                columns: operatorColumns,
                rows: mockOperatorRows,
              },
            },
            {
              title: "Validators",
              count: mockValidatorRows.length,
              tableProps: {
                columns: validatorColumns,
                rows: mockValidatorRows,
              },
            },
            ...(showPeerRankings
              ? [
                  {
                    title: "Peer Rankings",
                    count: mockPeerRankingRows.length,
                    tableProps: {
                      columns: peerRankingColumns,
                      rows: mockPeerRankingRows,
                    },
                  },
                ]
              : []),
          ]}
        />
      </BoxTable>
    </PageContainer>
  </DarkBackground>
);

// -- Story config --

export default {
  title: "Pages/ClusterDetailsPage",
  component: MockClusterDetailsPage,
  parameters: {
    layout: "fullscreen",
  },
  argTypes: {
    isLoading: { control: "boolean" },
    status: {
      control: "select",
      options: [
        "active",
        "activating",
        "exited",
        "exiting",
        "pending_activation",
        "awaiting_deposits",
        "awaiting_key_generation",
        "incomplete_definition",
        "slashed",
        "unknown",
      ],
    },
    showExitButton: { control: "boolean" },
    showPeerRankings: { control: "boolean" },
    showNetworkMismatch: { control: "boolean" },
  },
} satisfies Meta<typeof MockClusterDetailsPage>;

type Story = StoryObj<typeof MockClusterDetailsPage>;

